window.ScripturaLexicons.BDAG_PART_0353 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-01\" data-source=\"BDAG\" data-search=\"ταμεῖον, ου, τό substantivo neutro depósito; aposento interior BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταμεῖον, ου, τό</td><td>substantivo neutro</td><td>depósito; aposento interior</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-02\" data-source=\"BDAG\" data-search=\"ταμιεῖον, ου, τό substantivo neutro aposento secreto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταμιεῖον, ου, τό</td><td>substantivo neutro</td><td>aposento secreto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-03\" data-source=\"BDAG\" data-search=\"τανῦν remissão ver νῦν BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τανῦν</td><td>remissão</td><td>ver νῦν</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-04\" data-source=\"BDAG\" data-search=\"τάξις, εως, ἡ substantivo feminino ordem; posição; disposição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τάξις, εως, ἡ</td><td>substantivo feminino</td><td>ordem; posição; disposição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-05\" data-source=\"BDAG\" data-search=\"Ταουί̈α, ας, ἡ nome próprio feminino Távia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ταουί̈α, ας, ἡ</td><td>nome próprio feminino</td><td>Távia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-06\" data-source=\"BDAG\" data-search=\"ταπεινός, ή, όν adjetivo humilde; servil; despretensioso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταπεινός, ή, όν</td><td>adjetivo</td><td>humilde; servil; despretensioso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-07\" data-source=\"BDAG\" data-search=\"ταπεινοφρονέω verbo ser humilde; ser modesto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταπεινοφρονέω</td><td>verbo</td><td>ser humilde; ser modesto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-08\" data-source=\"BDAG\" data-search=\"ταπεινοφρόνησις, εως, ἡ substantivo feminino humildade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταπεινοφρόνησις, εως, ἡ</td><td>substantivo feminino</td><td>humildade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-09\" data-source=\"BDAG\" data-search=\"ταπεινοφροσύνη, ης, ἡ substantivo feminino humildade; modéstia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταπεινοφροσύνη, ης, ἡ</td><td>substantivo feminino</td><td>humildade; modéstia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-10\" data-source=\"BDAG\" data-search=\"ταπεινόφρων, ον adjetivo humilde BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταπεινόφρων, ον</td><td>adjetivo</td><td>humilde</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-11\" data-source=\"BDAG\" data-search=\"ταπεινόω verbo baixar; humilhar; mortificar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταπεινόω</td><td>verbo</td><td>baixar; humilhar; mortificar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-12\" data-source=\"BDAG\" data-search=\"ταπείνωσις, εως, ἡ substantivo feminino humilhação; humildade; mortificação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταπείνωσις, εως, ἡ</td><td>substantivo feminino</td><td>humilhação; humildade; mortificação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-13\" data-source=\"BDAG\" data-search=\"ταράσσω verbo agitar; perturbar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταράσσω</td><td>verbo</td><td>agitar; perturbar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-14\" data-source=\"BDAG\" data-search=\"ταραχή, ῆς, ἡ substantivo feminino agitação; inquietação; tumulto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταραχή, ῆς, ἡ</td><td>substantivo feminino</td><td>agitação; inquietação; tumulto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-15\" data-source=\"BDAG\" data-search=\"τάραχος, ου, ὁ substantivo masculino agitação mental; distúrbio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τάραχος, ου, ὁ</td><td>substantivo masculino</td><td>agitação mental; distúrbio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-16\" data-source=\"BDAG\" data-search=\"Ταρσεύς, έως, ὁ gentílico masculino tarsense BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ταρσεύς, έως, ὁ</td><td>gentílico masculino</td><td>tarsense</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-17\" data-source=\"BDAG\" data-search=\"Ταρσός, οῦ, ἡ topônimo feminino Tarso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ταρσός, οῦ, ἡ</td><td>topônimo feminino</td><td>Tarso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-18\" data-source=\"BDAG\" data-search=\"ταρταρόω verbo manter cativo no Tártaro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταρταρόω</td><td>verbo</td><td>manter cativo no Tártaro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-19\" data-source=\"BDAG\" data-search=\"τάσσω verbo dispor; ordenar; determinar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τάσσω</td><td>verbo</td><td>dispor; ordenar; determinar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0353-20\" data-source=\"BDAG\" data-search=\"ταῦ, τό substantivo neutro tau; numeral 300 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταῦ, τό</td><td>substantivo neutro</td><td>tau; numeral 300</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0353-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμεῖον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταμεῖον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (esta forma contraída do mais antigo <span class=\"greek\">ταμιεῖον</span> [q.v.] encontra-se já no primeiro século a.C. em inscr. [SIG 783, 37] e pap. [BGU 1115, 41], mas não se torna muito comum senão no início de nossa era. Cf. Plut., Mor. 9d; Babrius, Fab. 108, 2 L-P.; LXX [Thackeray 63.—Rahlfs insere a forma não contraída no texto todas as vezes que a palavra é usada]; En 11:1; TestSol 13:2; TestAbr; Philo, Omn. Prob. Lib. 86. V. também Lob., Phryn. 493; Mayser 92; B-D-F §31, 2; W-S. §5:23b; Mlt. 44f; Mlt-H. 89f; Nachmanson 71; PKatz-Walters, The Text of the Septuagint ’73, 94f. Empréstimo rabínico <span class=\"hebrew\" dir=\"rtl\">טַמְיוֹן</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> lugar para guardar objetos de valor, depósito (a palavra tem este sentido em Thu. et al.; frequentemente pap., LXX) com <span class=\"greek\">ἀποθήκη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:24</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> em geral, um aposento no interior de uma casa, aposento interior (assim X., Hell. 5, 4, 6 v.l.; Gen 43:30; Ex 7:28; SSol 1:4, e frequentemente na LXX; TestAbr B 5 p. 109, 24 [Stone p. 66]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:6</a> (TestJos 3:3). <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ταμείοις</span> num dos aposentos interiores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:3</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ταμεῖα</span> 1 Cl 50:4 (cf. Is 26:20).—DELG s.v. <span class=\"greek\">ταμία</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταμιεῖον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταμιεῖον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (cf. artigo precedente; Thu.+; inscr. e pap. mais antigos; PsSol 4:8; TestSim 8:3; TestJos 3:3; JosAs 2:9; EpArist 111 [sobre isto HMeecham, The Letter of Aristeas ’35, 79]; Jos., Bell. 2, 17, Ant. 8, 410; 18, 312) aposento oculto, secreto, fig. <span class=\"greek\">τὰ</span> <span class=\"greek\">ταμιεῖα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γαστρός</span> 1 Cl 21:2 (Pr 20:21). No NT somente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:26</a> como v.l. escassamente atestada (B-D-F §31, 2; Mlt.-H. 89). De N13 a N25 imprimem-se sempre as formas não contraídas.—OGI I p. 278 n. 32. DELG s.v. <span class=\"greek\">ταμία</span>. M-M. s.v. <span class=\"greek\">ταμεῖον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τανῦν</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τανῦν</span> v. <span class=\"greek\">νῦν</span> 2b.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάξις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τάξις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (Aeschyl., Hdt.+; empréstimo na literatura rabínica).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> disposição de coisas em sequência, sucessão/ordem fixa (Epict. 3, 2, 2; Appian, Bell. Civ. 4, 22 §92; TestNapht 2:8 <span class=\"greek\">ἐν</span> <span class=\"greek\">τάξει</span>) <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">τάξει</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐφημερίας</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:8</a> (MAvi-Yonah, The Caesarea Inscription of the Twenty-Four Priestly Courses, in The Teacher’s Yoke [in mem. HTrantham], ed. JVardaman/JGarrett, ’64, 46–57). Sem <span class=\"greek\">ἐν</span>: <span class=\"greek\">τάξει</span> em ordem (estritamente cronológica) Papias (2:15), embora JKleist, trad. ’48, 207f, nota 19, prefira literalmente, palavra por palavra. HRigg, Jr., NovT 1, ’56, 171: emenda para <span class=\"greek\">τάχει</span>=de maneira descuidada.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> estado de boa ordem, ordem, procedimento adequado <span class=\"greek\">πάντα</span> <span class=\"greek\">τάξει</span> <span class=\"greek\">ποιεῖν</span> 1 Cl 40:1. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τάξιν</span> em ordem, de maneira ordenada, provavelmente ‘um após o outro’ (Lucian, Alex. 46; Alex. Aphr., Quaest. 1, 4, 1 p. 10, 17 Br.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.40\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:40</a> (cf. as regras dos Iobakchoi: IG II2, 1368); Dg 8:7.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:5</a>.—HvCampenhausen, Tradition and Life in the Church, ’68, 123–40.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> posto ou categoria atribuídos, posição, cargo (tem-se uma responsabilidade num sistema ordenado de coisas: Hyperid. 3, 30; Demosth. 18, 258; Diod S 15, 64, 4; Epict. 1, 29, 39 [atribuído por Deus]; Diog. L. 9, 21, final; 1 Esdr 1:15; ApcMos 38; Jos., Vi. 397, Ant. 7, 36) <span class=\"greek\">εἰς</span> <span class=\"greek\">τοσαύτην</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">τάξιν</span> <span class=\"greek\">ἔθετο</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> Deus os designou (isto é, os cristãos) para tão elevada posição Dg 6:10 (quanto à perspectiva greco-romana, v. Reader, Polemo 345–47).—Administração (de um cargo) Papias (4); v. artigo <span class=\"greek\">συμβαίνω</span> 2.</p><p class=\"entry-text\"><span class=\"sense-number\">④</span> disposição em que alguém ou algo funciona, disposição, natureza, maneira, condição, aspecto exterior (2 Macc 1:19 <span class=\"greek\">φρέατος</span> <span class=\"greek\">τάξιν</span> <span class=\"greek\">ἔχοντος</span> <span class=\"greek\">ἄνυδρον</span> de um poço que tinha uma configuração própria de uma área seca; Polyb. 3, 20, 5; Diod S 1, 25, 5; EpArist 69 <span class=\"greek\">κρηπίδος</span> <span class=\"greek\">ἔχουσα</span> <span class=\"greek\">τάξιν</span>=‘tinha a aparência de um calçado’) <span class=\"greek\">ἡ</span> <span class=\"greek\">νεωτερικὴ</span> <span class=\"greek\">τάξις</span> a natureza ou aparência juvenil IMg 3:1. Talvez seja deste modo que Hb entendeu Ps 109:4b, que o autor interpreta no sentido de que Jesus era sumo sacerdote <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τάξιν</span> <span class=\"greek\">Μελχισέδεκ</span> segundo a natureza de = tal como Melquisedeque, isto é, segundo o tipo de disposição estabelecida para o exercício da função de M.: 5:6, 10; 6:20; 7:11a, 17, 21 v.l. Em todo caso, a referência não é somente à ‘categoria’ superior, mas também à natureza inteiramente diversa do sacerdócio de Melquisedeque em comparação com o de Arão 7:11b. (Em Mitt-Wilck. I/2, 81, 16; 19 e al. em pap. <span class=\"greek\">τάξις</span>=posição de um sacerdote.)—AcPl Ha 8, 18=BMM recto 23 (restauração certa, v. Ox 1602, 21).—DELG s.v. <span class=\"greek\">τάσσω</span>. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταουί̈α, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ταουί̈α</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> Távia, cristã de Esmirna de resto desconhecida ISm 13:2 (<span class=\"greek\">Ταουί̈α</span> é a forma do nome no ms. gr. e na versão lat. Não se encontra em outro lugar. Mas encontramos <span class=\"greek\">Ταουις</span> como nome de mulher PLond II, 258, 184 p. 33, e <span class=\"greek\">Ταουεις</span> PLond II, 257, 212 p. 26; 245 p. 27, bem como o masc. lat. Tavius, por ex. CIL III 6248.—O gr. interpolado e o armênio têm <span class=\"greek\">Γαουί̈α</span>.)</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπεινός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταπεινός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (Pind., Aeschyl., Hdt.+; pap., LXX; En 26, 4 e Did., Gen. 220, 7 [<span class=\"greek\">ὄρος</span>]; PsSol 5:12; Test12Patr; JosAs 28:3 cód. A al.; ApcSed, EpArist, Philo, Joseph.; Theoph. Ant. 2, 13 [p. 132, 3]) geralmente ‘baixo’, em nossa literatura somente em sentido fig.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> relativo a estar em condição social baixa ou à relativa incapacidade de enfrentar as circunstâncias, humilde, sem distinção, sem importância (Hdt. 7, 14; Pla., Phd. 257c; Isocr. 3, 42 al.; 1 Km 18:23; Jos., Bell. 4, 365, Ant. 7, 95; 13, 415; Did., Gen. 244, 14.—Orig., C. Cels. I, 56, 4) <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀδελφὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ταπ</span>. (oposto <span class=\"greek\">πλούσιος</span>, alguém que tem mais controle da vida que o <span class=\"greek\">τ</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:9</a>.—Subst. (Philo, Poster. Cai. 109; Jos., Bell. 4, 319) B 3:3. Pl. (Heraclides Pont., Fgm. 55 W. <span class=\"greek\">ταπεινοί</span> ao lado de <span class=\"greek\">δοῦλοι</span>; Diod S 14, 5, 4; Menand., Monost. 412 Mei. [608 Jaekel]; Ps.-Callisth. 2, 16, 10 da Fortuna: <span class=\"greek\">ἢ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ταπεινοὺς</span> <span class=\"greek\">ὑπεράνω</span> <span class=\"greek\">νεφῶν</span> <span class=\"greek\">τιθεῖ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὕψους</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ζόφον</span> <span class=\"greek\">κατήγαγεν</span>; Zeph 2:3; Is 11:4; 14:32) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:52</a> (oposto <span class=\"greek\">δυνάσται</span>, que dispõem dos recursos para enfrentar as circunstâncias). <span class=\"greek\">ὁ</span> <span class=\"greek\">παρακαλῶν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ταπεινούς</span> aquele que encoraja os abatidos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:6</a> (Is 49:13). Sobre <span class=\"greek\">τοῖς</span> <span class=\"greek\">ταπεινοῖς</span> <span class=\"greek\">συναπαγόμενοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:16</a> v. <span class=\"greek\">συναπάγω</span>. 1 Cl 59:3f provavelmente pertence aqui (mas v. 3 abaixo); também B 14:9 (Is 61:1 v.l.).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> relativo a ser servil na maneira de agir, dócil, subserviente, abjeto, qualidade negativa que faria alguém perder a dignidade no mundo greco-romano, oposta à conduta de uma pessoa livre (X., Mem. 3, 10, 5; Pla., Leg. 6, 774c; Demochares [III a.C.]: 75 Fgm. 1 Jac. <span class=\"greek\">αἰσχρὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ταπεινά</span>; Cass. Dio 74, 5; POxy 79 II, 2 [II d.C.]) num juízo pronunciado pelos adversários de Paulo a seu respeito <span class=\"greek\">κατὰ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">ταπεινός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:1</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> relativo a ser despretensioso, humilde (Aeschyl. et al.; Pla., Leg. 4, 716a; X., Ag. 11, 11 numa descrição de Agesilau, que não se deixa envaidecer pelo sucesso ou pela posição; PGen 14, 6; LXX; EpArist 263; TestGad 5:3; Orig., C. Cels. 3, 64, 6) <span class=\"greek\">ταπεινὸς</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span> (com <span class=\"greek\">πραΰς</span>, q.v.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:29</a>. Subst. pl., oposto (<span class=\"greek\">οἱ</span>) <span class=\"greek\">ὑψηλοί</span> 1 Cl 59:3 (mas v. 1 acima); B 19:6; D 3:9. Oposto <span class=\"greek\">ὑπερήφανοι</span> (segundo Pr 3:34) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:5</a>; 1 Cl 30:2. <span class=\"greek\">τὸ</span> <span class=\"greek\">ταπεινὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span> humildade da alma 55:6. RLeivestad, <span class=\"greek\">ΤΑΠΕΙΝΟΣ</span>-<span class=\"greek\">ΤΑΠΕΙΝΟΦΡΩΝ</span>, NovT 8, ’66, 36–47. V. <span class=\"greek\">πραΰτης</span>.—DELG. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπεινοφρονέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταπεινοφρονέω</span> (<span class=\"greek\">ταπεινός</span>, <span class=\"greek\">φρήν</span>) imperf. <span class=\"greek\">ἐταπεινοφρόνουν</span>; fut. <span class=\"greek\">ταπεινοφρονήσω</span>; 1 aor. <span class=\"greek\">ἐταπεινοφρόνησα</span> (Epict. 1, 9, 10 em sentido pejorativo) ser humilde no pensamento ou na conduta, ser modesto, despretensioso (Ps 130:2; SibOr 8, 480; Rhet. Gr. I 624, 29) 1 Cl 13:3; 16:17; 17:2; 38:2; 48:6; Hs 5, 3, 7; 7:6. Oposto <span class=\"greek\">ἀλαζονεύεσθαι</span> 1 Cl 2:1; cf. 13:1; 16:2. Oposto <span class=\"greek\">ἐπαίρεσθαι</span> 16:1. Com <span class=\"greek\">ἐγκρατεύεσθαι</span> 30:3. <span class=\"greek\">ταπ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> ser humilde para com Deus 62:2 (v. <span class=\"greek\">ὁ</span> 2e e B-D-F §160; também Rob. 486f). <span class=\"greek\">ταπεινοφρονῆσαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">πράξει</span> <span class=\"greek\">αὐτοῦ</span> ser humilde em tudo quanto faz Hs 7:4.—DELG s.v. <span class=\"greek\">ταπεινά</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπεινοφρόνησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταπεινοφρόνησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ταπεινός</span>, <span class=\"greek\">φρόνησις</span>) humildade com <span class=\"greek\">μακροθυμία</span> Hs 8, 7, 6 v.l.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπεινοφροσύνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταπεινοφροσύνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (v. precedente; Epict. 3, 24, 56; Jos., Bell. 4, 494, ambos em sentido pejorativo) em nossa literatura somente em sentido favorável (<span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δόγμα</span> Orig., C. Cels. 6, 15, 23; <span class=\"greek\">ταπεινοφροσύνης</span> <span class=\"greek\">σωτήριον</span> Did., Gen. 70, 26) humildade, modéstia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:3</a> (em dat. de causa motivadora); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:5</a>; 1 Cl 21:8; Hs 5, 3, 7 (da humildade que se exprime pelo jejum; Leutzsch, Hermas 425f, n. 441). Com <span class=\"greek\">ἐπιείκεια</span> 1 Cl 56:1; cf. 58:2. Com <span class=\"greek\">ἐπιείκεια</span> e <span class=\"greek\">πραΰτης</span> 30:8. Com <span class=\"greek\">πραΰτης</span>, <span class=\"greek\">μακροθυμία</span> e outras virtudes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:12</a>; cf. 2:23. <span class=\"greek\">μετὰ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">ταπ</span>. com toda a humildade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:2</a> (+ <span class=\"greek\">καὶ</span> <span class=\"greek\">πραΰτητος</span>); sem <span class=\"greek\">πάσης</span> 1 Cl 31:4; 44:3. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἐρώτησις</span> <span class=\"greek\">ταπεινοφροσύνης</span> <span class=\"greek\">χρῄζει</span> toda oração requer humildade Hv 3, 10, 6. A humildade também pode ser mal orientada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:18</a>, 23.—Bibliografia s.v. <span class=\"greek\">πραΰτης</span> e <span class=\"greek\">ταπεινόω</span> 4. Também KDeissner, D. Idealbild d. stoischen Weisen 1930; Vögtle (s.v. <span class=\"greek\">πλεονεξία</span>) lista de palavras; LGilen, Demut des Christen nach d. NT: ZAszMyst 13, ’38, 266–84; LMarshall, Challenge of NT Ethics ’47, 92–96; ADihle, Demut: RAC III ’56, 735–78 [bibliografia]; SRehol, Das Problem der Demut in der profan-griechischen Literatur im Vergleich zu Septuaginta und NT ’61.—DELG s.v. <span class=\"greek\">ταπεινός</span>. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπεινόφρων, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταπεινόφρων</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ταπεινός</span>, <span class=\"greek\">φρήν</span>) gen. -<span class=\"greek\">ονος</span> (em Plut. Mor. 336e; 475e e Iambl., Protr. 21, 15 p. 115, 23 Pistelli=‘pusilânime’) em nossa literatura humilde (Pr 29:23; Leontius 26 p. 56, 22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:8</a> (v.l. <span class=\"greek\">φιλόφρονες</span>); B 19:3; Hm 11:8 (com <span class=\"greek\">πραΰς</span> e outros adjetivos). <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">μεγαλορημοσύνας</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">ταπεινόφρονες</span> deveis ser humildes em contraste com a jactância deles IEph 10:2 (com <span class=\"greek\">πραεῖς</span>).—Subst. <span class=\"greek\">ὁ</span> <span class=\"greek\">ταπεινόφρων</span> 1 Cl 38:2 v.l. <span class=\"greek\">τὸ</span> <span class=\"greek\">ταπεινόφρον</span> humildade 19:1. V. Leivestad s.v. <span class=\"greek\">ταπεινός</span>.—DELG s.v. <span class=\"greek\">ταπεινός</span>. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπεινόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταπεινόω</span> (<span class=\"greek\">ταπεινός</span>) fut. <span class=\"greek\">ταπεινώσω</span>; 1 aor. <span class=\"greek\">ἐταπείνωσα</span>. Pass.: 1 fut. <span class=\"greek\">ταπεινωθήσομαι</span>; 1 aor. <span class=\"greek\">ἐταπεινώθην</span>; perf. part. <span class=\"greek\">τεταπεινωμένος</span> (Hippocr. et al.; LXX; En 106:1; EpArist 257; Philo, Joseph.) geralmente ‘baixar, tornar baixo’</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> fazer que esteja num ponto mais baixo, baixar (Diod S 1, 36, 8; Bar 5:7; En 1:6; PsSol 11:4) <span class=\"greek\">ὄρος</span>, <span class=\"greek\">βουνόν</span> nivelar uma montanha, colina <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:5</a> (Is 40:4).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> fazer alguém perder prestígio ou posição, humilhar, vexar, rebaixar, feito especialmente a escravos, extensão fig. de 1</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> com ênfase na inversão de posição <span class=\"greek\">ταπ</span>. <span class=\"greek\">ἑαυτόν</span> humilhar-se, de Cristo, que voluntariamente foi à morte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:8</a> (sobre toda a passagem, v. a bibliografia s.v. <span class=\"greek\">ἁρπαγμός</span> e <span class=\"greek\">κενόω</span> 1b; também KThieme, D. <span class=\"greek\">ταπεινοφροσύνη</span> Phil 2 u. Ro 12: ZNW 8, 1907, 9–33). De Paulo, que não hesitou em trabalhar com as próprias mãos, rebaixar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:7</a>. <span class=\"greek\">ὅστις</span> <span class=\"greek\">ταπεινώσει</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ὑψωθήσεται</span> (<span class=\"greek\">ταπ</span>. … <span class=\"greek\">ὑψόω</span>: Chilon em Diog. L. 1, 69) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:12b</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:11b</a>; 18:14b (v. também 2b abaixo). Também o pass. (Hyperid. 6, 10; Jos., Ant. 18, 147) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:12a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:11a</a>; 18:14a (cf. X., An. 6, 3, 18 <span class=\"greek\">θεὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">μεγαληγορήσαντας</span> <span class=\"greek\">ταπεινῶσαι</span> <span class=\"greek\">βούλεται</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> com ênfase no envergonhar, com acus. de pessoa ou coisa tratada deste modo (Diod S 8, 25, 1; Orig., C. Cels. 3, 62, 29) <span class=\"greek\">μὴ</span> <span class=\"greek\">ταπεινώσῃ</span> <span class=\"greek\">με</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span> para que Deus não me humilhe diante de vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:21</a>. <span class=\"greek\">κύριος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐταπείνωσέν</span> <span class=\"greek\">με</span> <span class=\"greek\">σφόδρα</span> o Senhor Deus me envergonhou profundamente GJs 2:3. <span class=\"greek\">τὶ</span> <span class=\"greek\">ἐταπείνωσας</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span> <span class=\"greek\">σοὺ</span>; Por que te desonraste tanto? GJs 13:2; 15:3.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> com ênfase no aspecto punitivo (Diod S 13, 24, 6 Tique [Fortuna] <span class=\"greek\">ταπεινοῖ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὑπερηφάνους</span>; Cyranides p. 49, 12 <span class=\"greek\">ἐχθρούς</span>) confundir, derrubar <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὑψηλούς</span> 1 Cl 59:3b; <span class=\"greek\">ὕβριν</span> <span class=\"greek\">ὑπερηφάνων</span> v. 3a. Cf. B 4:4f (Da 7:24).—<span class=\"greek\">ταπεινόω</span> pode também referir-se a perdas externas, aproximadamente = ‘oprimir, prejudicar’ (Petosiris, Fgm. 6 linha 21 [ativo] e 24 [pass.]).</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> fazer que seja ou se torne humilde na atitude, humilhar, tornar humilde em sentido favorável (Philod., <span class=\"greek\">περὶ</span> <span class=\"greek\">κακιῶν</span> col. 22, 3 = p. 38 Jensen <span class=\"greek\">ἑαυτόν</span>; Celsus 3, 62 <span class=\"greek\">αὑτόν</span>) <span class=\"greek\">ὅστις</span> <span class=\"greek\">ταπεινώσει</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">παιδίον</span> <span class=\"greek\">τοῦτο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:4</a>. Assim talvez também 23:12b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:11b</a>; 18:14b (v. 2a acima). <span class=\"greek\">ταπεινοῦσθαι</span> humilhar-se, tornar-se humilde (Menand., Fgm. 754, 6 Kö.=544, 6 Kock <span class=\"greek\">τὴν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἐξιλάσαντο</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ταπεινοῦσθαι</span> <span class=\"greek\">σφόδρα</span>; Sir 18:21; GrBar 7:5 <span class=\"greek\">ἐταπεινώθην</span> <span class=\"greek\">φόβῳ</span> <span class=\"greek\">μεγάλῳ</span>) <span class=\"greek\">ταπεινώθητε</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:10</a>. <span class=\"greek\">ταπεινώθητε</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> curvai-vos sob a mão de Deus (cf. Gen 16:9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:6</a>. <span class=\"greek\">καρδία</span> <span class=\"greek\">τεταπεινωμένη</span> um coração humilhado 1 Cl 18:17 (Ps 50:19). <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">τεταπεινωμένη</span> B 3:5 (Is 58:10.—Cf. Diod S 20, 53, 3 <span class=\"greek\">τῇ</span> <span class=\"greek\">ψυχῇ</span> <span class=\"greek\">ταπεινωθείς</span>; 20, 77, 3 <span class=\"greek\">ἐταπεινώθη</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span>). Correspondentemente <span class=\"greek\">ὀστᾶ</span> <span class=\"greek\">τεταπεινωμένα</span> 1 Cl 18:8 (Ps 50:10).—KThieme, D. christl. Demut I (história da palavra e humildade em Jesus) 1906; DFyffe, ET 35, 1924, 377–79. V. também <span class=\"greek\">πραΰτης</span>, final.</p><p class=\"entry-text\"><span class=\"sense-number\">④</span> sujeitar a disciplina rigorosa, constranger, mortificar. De acordo com o uso do AT, <span class=\"greek\">ταπεινοῦν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">ψυχήν</span> (Lev 16:29, 31; 23:27; Ps 34:13; Is 58:3 al.) ou <span class=\"greek\">ταπεινοῦσθαι</span> (Sir 34:26; 2 Esdr 8:21; as orações por vingança de Reneia [Dssm., LO 353f, LAE 413ff=SIG 1181, 11] <span class=\"greek\">θεὸς</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">ταπεινοῦται</span>; v. Dssm., LO 357f, LAE 419) significa mortificar-se GJs 2:2; B 3:1, 3 (Is 58:5); Hm 4, 2, 2 (v. <span class=\"greek\">ταπεινοφροσύνη</span>). <span class=\"greek\">οἶδα</span> <span class=\"greek\">ταπεινοῦσθαι</span> (oposto <span class=\"greek\">περισσεύειν</span>) de um regime austero: sei viver com pouco (cf. <span class=\"greek\">ταπεινός</span> Pla. Leg. 762e; v. também Plut., Mor. 7e) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:12</a>.—WCvanUnnik, Zur Bedeutung von <span class=\"greek\">ταπεινοῦν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span> bei den Apost. Vätern, ZNW 44, ’52f, 250–55. Sobre a palavra em seu conjunto: ESchweizer, Erniedrigung u. Erhöhung bei Jesus u. s. Nachfolgern ’55.—DELG s.v. <span class=\"greek\">ταπεινός</span>. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταπείνωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταπείνωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ταπεινόω</span>; Pla., Aristot. et al.; OGI 383, 201 [I a.C.]; LXX, Test12Patr; JosAs 11:1; 13:1 cód. A [p. 57, 1 Bat. al.]; Philo, Joseph.).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> experiência de uma reversão da fortuna, humilhação como experiência (Epict. 3, 22, 104; PsSol 2:35; TestJud 19:2; Jos., Bell. 2, 604, Ant. 2, 234) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:33</a>; 1 Cl 16:7 (ambos Is 53:8). <span class=\"greek\">καυχάσθω</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πλούσιος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ταπεινώσει</span> <span class=\"greek\">αὐτοῦ</span> glorie-se o rico (dito ironicamente) em seu rebaixamento/ruína <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:10</a> (BWeiss, Beyschlag, Windisch, MDibelius, FHauck). Em Diod S 11, 87, 2 <span class=\"greek\">ταπείνωσις</span> é a limitação imposta ao patrimônio de um homem rico. Em Petosiris, Fgm. 6 linhas 5; 11; 29 a palavra significa a humilhação ou depressão causada por graves perdas externas, algo como um colapso.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> estado ou condição despretensiosa, humildade, modéstia, posição humilde (Diod S 2, 45, 2; Horapollo 1, 6; TestAbr B 7 p. 111, 20 [Stone p. 70, oposto <span class=\"greek\">ὕψος</span>]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:20</a> D. <span class=\"greek\">ἐπιβλέπειν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ταπ</span>. <span class=\"greek\">τινος</span> olhar para a posição humilde de alguém, isto é, mostrar solicitude por alguém em circunstâncias humildes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:48</a> (cf. 1 Km 1:11; 9:16; Ps 30:8.—HToxopeüs, Lc. 1:48a: TT 45, 1911, 389–94). <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ταπ</span>. o corpo humilde, do corpo material em contraste com o corpo glorificado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:21</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> conduta de autorrebaixamento, autorrebaixamento, mortificação (<span class=\"greek\">ταπεινόω</span> 4) com <span class=\"greek\">νηστεία</span> (cf. PsSol 3:8; TestJos 10:2; JosAs 11:1) 1 Cl 53:2; 55:6.—DELG s.v. <span class=\"greek\">ταπεινός</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταράσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταράσσω</span> imperf. <span class=\"greek\">ἐτάρασσον</span>; fut. 3 sg. <span class=\"greek\">ταράξει</span> LXX; 1 aor. <span class=\"greek\">ἐτάραξα</span>. Pass.: imperf. <span class=\"greek\">ἐταρασσόμην</span>; fut. 3 sg. <span class=\"greek\">ταραχθήσεται</span>; 1 aor. <span class=\"greek\">ἐταράχθην</span>; perf. <span class=\"greek\">τετάραγμαι</span>, part. <span class=\"greek\">τεταραγμένος</span> (Hom.+; Ath., R. 3 p. 51, 30 [-<span class=\"greek\">ττ</span>]).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> causar movimento sacudindo ou agitando, sacudir conjuntamente, agitar, de água (Hom. et al.; Aesop 155 P.=274b Halm//160 H-H; Babrius 166, 5=Fgm. 4 p. 144 L-P.; Athen. 7, 52, 298c <span class=\"greek\">ταραττομένου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὕδατος</span>; Hos 6:8; Is 24:14; Ezk 32:2, 13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:3</a> [4] v.l.; pass. (Solon 11 Diehl3) ser movido, ser agitado v. 7.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> causar perturbação interior, agitar, perturbar, inquietar, lançar em confusão, extensão fig. de 1 (Aeschyl., Hdt. et al., pap., LXX; Just., A I, 68, 7 [Adriano]; Ath., R. 3 p. 51–30), em nossa literatura de agitação e confusão mentais e espirituais (Menand., Epitr. 611 Kö. [mas v. 931 S. mg.]; Philo, Conf. Lingu. 69), que podem manifestar-se em tumulto exterior <span class=\"greek\">τὸν</span> <span class=\"greek\">ὄχλον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:8</a>; cf. v. 13 (Hyperid. 1, 31, 8; POxy 298, 27; PGiss 40 II, 20 <span class=\"greek\">ταράσσουσι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span>). <span class=\"greek\">τὴν</span> <span class=\"greek\">διάνοιάν</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ταρ</span>. 2 Cl 20:1 (Epict., Ench. 28 <span class=\"greek\">τ</span>. <span class=\"greek\">γνώμην</span> <span class=\"greek\">σου</span>). De confusão mental causada por falsos ensinamentos <span class=\"greek\">ταρ</span>. <span class=\"greek\">τινά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:24</a> (seguido de <span class=\"greek\">λόγοις</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:7</a>; 5:10. De Jesus no Evangelho de João <span class=\"greek\">ἐτάραξεν</span> <span class=\"greek\">ἑαυτόν</span> ele ficou perturbado ou agitado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:33</a> (diferentemente NRSV ‘profundamente comovido’. V. Hdb. ad loc.—Menand., Sam. 672 S. [327 Kö.] <span class=\"greek\">σαυτὸν</span> <span class=\"greek\">ταράττεις</span>; M. Ant. 4, 26 <span class=\"greek\">σεαυτὸν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">τάρασσε</span>).—Pass. ficar perturbado, assustado, aterrorizado (Ps 47:6; Is 8:12; Jos., Ant. 7, 153; 12, 164; Just., D. 38, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:3</a> (GJs 21:2); 14:26 (cf. Phlegon: 257 Fgm. 36, II, 3 com <span class=\"greek\">θαρρεῖν</span>, diante de um <span class=\"greek\">φάσμα</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:12</a>; 24:38; MPol 5:1; 12:1; Hm 12, 4, 2. <span class=\"greek\">μηδὲ</span> <span class=\"greek\">ταραχθῆτε</span> não vos deixeis intimidar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:14</a> (Is 8:12). <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχή</span> <span class=\"greek\">μου</span> <span class=\"greek\">τετάρακται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:27</a> (cf. Diod S 17, 112, 4 Alexandre <span class=\"greek\">ἐταράττετο</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span> diante da predição de sua morte; Dio Chrys. 23 [40], 20 <span class=\"greek\">ταράξαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span>; Chion, Ep. 16, 7 <span class=\"greek\">ταράσσειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span>; Ps 6:4; TestZeb 8:6; TestDan 4:7b); também <span class=\"greek\">ἡ</span> <span class=\"greek\">καρδία</span> 14:1, 27 (cf. Ps 108:22; 54:5; TestDan 4:7a). <span class=\"greek\">ταραχθῆναι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span> ficar interiormente comovido 13:21; cf. 11:33 v.l. (Ps.-Callisth. 2, 12, 5 <span class=\"greek\">ἐταράσσετο</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ψυχῇ</span>).—DELG. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταραχή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταραχή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ταράσσω</span>; Pind., Hdt.+; inscr., pap., LXX; TestSol 10:29 C; TestJob, Test12Patr, EpArist, Philo, Joseph.; empréstimo na literatura rabínica) geralmente em referência a uma perturbação da ordem habitual.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> movimento de algo causado por agitação, agitação de água que geralmente estava quieta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:3</a> [4] v.l.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> perturbação interior, perplexidade, inquietação, extensão fig. de 1 (Thu., Pla., LXX; Jos., Ant. 14, 273 com <span class=\"greek\">φόβος</span>) IEph 19:2.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> perturbação das relações cívicas normais, distúrbio, tumulto, rebelião, extensão fig. de 1 (Hdt. et al.; OGI 90, 20; PAmh 30, 10 [II a.C.]; Mitt-Wilck. I/2, 167, 14 [II a.C.]; 3 Macc 3:24; Jos., Bell. 1, 216) pl. (Diod S 5, 40, 1 <span class=\"greek\">ταραχαί</span>=confusão; Artem. 1, 17; 52 al.; TestDan 5:2; Jos., Vi. 103) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:8</a> v.l.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάραχος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τάραχος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ταράσσω</span>; desde Hippocr. I 604; VI 112 L.; X.; BGU 889, 23 [II d.C.]; LXX; Jos., Bell. 4, 495)=<span class=\"greek\">ταραχή</span>.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> estado de agitação mental (X., An. 1, 8, 2; Epicurus em Diog. L. 10, 77; 82 <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ψυχαῖς</span>; Aretaeus p. 142, 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:18</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> estado de inquietação cívica, distúrbio, comoção (Appian, Bell. Civ. 5, 87 §365) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:23</a> (em ambas as passagens <span class=\"greek\">τάραχος</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὀλίγος</span>. No mesmo sentido Chion, Ep. 3, 2 <span class=\"greek\">πολὺς</span> <span class=\"greek\">τάραχος</span>; PLampe, BZ 36, ’92, 69 [inscr.]).—DELG s.v. <span class=\"greek\">ταράσσω</span>. M-M. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταρσεύς, έως, ὁ</h1><div class=\"entry-meta\"><span>gentílico masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ταρσεύς</span>, <span class=\"greek\">έως</span>, <span class=\"greek\">ὁ</span> (Apollodorus [II a.C.]: 244 Fgm. 55 Jac.; Strabo 14, 5, 14; Arrian, Anab. 2, 4, 7; Plut., Mar. 433 [46, 2] al.; inscr. [v. New Docs 4, 173]; 2 Macc 4:30) pessoa de Tarso, tarsense, de Paulo, que (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:3</a>) nasceu em Tarso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:11</a>; 21:39. Schürer III 133, sobre a cidadania de Paulo.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ταρσός, οῦ, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ταρσός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ἡ</span> (a forma sing. do nome em Diod S 14, 20, 2; Strabo 14, 5, 9; Dio Chrys. 16 [33], 17; 17 [34], 46; Arrian, Anab. 2, 4, 7; Joseph., inscr.) Tarso, capital da Cilícia no sudeste da Ásia Menor (Diod S, loc. cit., <span class=\"greek\">μεγίστη</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Κιλικίᾳ</span> <span class=\"greek\">πόλεων</span>), famosa como centro da cultura erudita grega <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:30</a>; 11:25; 21:39 D; 22:3 (<span class=\"greek\">Τ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Κιλικίας</span> como Diod S 20, 108, 2; Xenophon Eph. 2, 13, 5; Jos., Ant. 9, 208).—WRamsay, The Cities of St. Paul 1907, 85–244; HBöhlig, Die Geisteskultur v. Tarsos 1913; HSteinmann, Z. Werdegang d. Pls. D. Jugendzeit in Tarsus 1928; WvanUnnik, Tarsus or Jerusalem ’62; AJones, The Cities of the Eastern Roman Provinces2 ’71; Pauly-W. IV 2413–39; Kl. Pauly V 529f; BHHW III 1933; Haenchen sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:3</a>. V. também CHemer, Acts índice; v. também s.v. <span class=\"greek\">Κιλικία</span>.—PECS 883f. Schürer III 33f (bibliografia).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταρταρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταρταρόω</span> (<span class=\"greek\">Τάρταρος</span> ‘o mundo subterrâneo’) 1 aor. <span class=\"greek\">ἐταρτάρωσα</span> (Acusilaus Hist. [V a.C.]: 2 Fgm. 8 Jac. I p. 50; Lydus, Men. 4, 158 p. 174, 26 W.; cf. Sext. Emp., Pyrrh. Hypot. 3, 24, 210 <span class=\"greek\">ὁ</span> <span class=\"greek\">Ζεὺς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Κρόνον</span> <span class=\"greek\">κατεταρτάρωσεν</span> [este composto várias vezes em Ps.—Apollod.: 1, 1, 4; 1, 2, 1, 2; 1, 2, 3]. O Tártaro, concebido pelos gregos como lugar subterrâneo mais baixo que o Hades, onde se infligia punição divina, e assim considerado também na apocalíptica israelita: Job 41:24; En 20:2; Philo, Exs. 152; Jos., C. Ap. 2, 240; SibOr 2, 302; 4, 186) manter cativo no Tártaro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:4</a>.—DELG s.v. <span class=\"greek\">Τάρταρος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τάσσω</span> fut. <span class=\"greek\">τάξω</span> LXX; 1 aor. <span class=\"greek\">ἔταξα</span>; perf. <span class=\"greek\">τέταχα</span>. Méd.: 1 aor. <span class=\"greek\">ἐταξάμην</span>. Pass.: part. aor. n. sg. <span class=\"greek\">ταχθέν</span> EpJer 61, pl. <span class=\"greek\">ταγέντα</span> (TestJob 16:3); perf. <span class=\"greek\">τέταγμαι</span>, part. <span class=\"greek\">τεταγμένος</span> (Pind., Aeschyl., Pre-Socr., Hdt.+)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> estabelecer uma ordem de coisas mediante disposição, dispor, colocar em seu lugar</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> de uma estrutura de autoridade, pass. <span class=\"greek\">αἱ</span> <span class=\"greek\">οὖσαι</span> (<span class=\"greek\">ἐξουσίαι</span>) <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τεταγμέναι</span> <span class=\"greek\">εἰσίν</span> as (estruturas de autoridade) atualmente existentes são estabelecidas por Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:1</a> (cf. IAndrosIsis, Kyme, sobre o papel de Ísis na ordenação de diversas estruturas sociais, políticas e econômicas; alguns interpretam como metonímia dos ocupantes dos cargos, cf. Da 4:37b; Horace, Odes 1, 12, 13–16; 49–52; Vergil, Ecl. 3, 60f); de autoridade estabelecida em contraste com uma turba MPol 10:2 (<span class=\"greek\">τάσσεσθαι</span> <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span> como aqui, Eur., Iph. A. 1363; X., An. 1, 6, 6; 2, 6, 13; Simplicius In Epict. p. 60, 19 Düb. <span class=\"greek\">τεταγμένοι</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">θεοῦ</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> de uma pessoa colocada numa posição específica, usado com prep. <span class=\"greek\">τάσσειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινος</span> colocar alguém acima ou a cargo de alguém ou algo (Polyb. 5, 65, 7; inscr.; Mitt-Wilck. I/2, 11, 51 [II a.C.]; PRev 51, 9 [III a.C.]) pass. (Arrian, Anab. 3, 6, 7 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πῶν</span> <span class=\"greek\">χρημάτων</span>=a cargo das finanças; En 20:5; Jos., Ant. 2, 70; 7, 370.—<span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> Ath. 24, 3) <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἧς</span> (isto é, o caminho da luz) <span class=\"greek\">εἰσὶν</span> <span class=\"greek\">τεταγμένοι</span> <span class=\"greek\">φωταγωγοὶ</span> <span class=\"greek\">ἄγγελοι</span> B 18:1.—Sobre <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">τασσόμενος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:9</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:8</a> v. <span class=\"greek\">ἐξουσία</span> 4 (<span class=\"greek\">τάσσεσθαι</span> <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινα</span> ‘ser colocado sob o comando de alguém’ Polyb. 3, 16, 3; 5, 65, 7; Diod S 2, 26, 8; 4, 9, 5; OGI 56, 13 [237 a.C.] <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">τασσομένοις</span>; mas Just., D. 126, 5 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρί</span>).—<span class=\"greek\">τάσσειν</span> <span class=\"greek\">τινά</span> <span class=\"greek\">εἰς</span> atribuir alguém a uma (determinada) categoria, usado também com um substantivo abstrato (Pla., Rep. 2, 371c, Polit. 289e), pass. pertencer a, ser classificado entre os que possuem <span class=\"greek\">ὅσοι</span> <span class=\"greek\">ἦσαν</span> <span class=\"greek\">τεταγμένοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ζωὴν</span> <span class=\"greek\">αἰώνιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.48\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:48</a>.—<span class=\"greek\">τάσσειν</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">διακονίαν</span> dedicar-se a um serviço (cf. X., Mem. 2, 1, 11 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">δουλείαν</span> <span class=\"greek\">ἐμαυτὸν</span> <span class=\"greek\">τάττω</span>; Pla., Rep. 2, 371c <span class=\"greek\">τάττειν</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διακονίαν</span> <span class=\"greek\">ταύτην</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:15</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> dar instruções quanto ao que deve ser feito, ordenar, fixar, determinar, designar (Trag., Hdt. +; inscr., pap., LXX; TestJob 17:3; Just., A I, 17, 1 <span class=\"greek\">φόρους</span>, A II, 5, 2 <span class=\"greek\">νόμον</span>; Ath., R. 14 p. 64, 19 <span class=\"greek\">τὰ</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">τεταγμένα</span>)</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> ativo e pass., seguido de acus. com inf. (X., An. 3, 1, 25) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:2</a>; 18:2 v.l. <span class=\"greek\">περὶ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">τέτακταί</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ποιῆσαι</span> acerca de tudo quanto te foi ordenado fazer 22:10 (cf. X., Resp. Lac. 11, 6). <span class=\"greek\">ὁ</span> <span class=\"greek\">τεταγμένος</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">δρόμος</span> o curso que foi fixado por ele (isto é, por Deus) 1 Cl 20:2 (cf. Philo, Poster. Cai. 144, Rer. Div. Her. 97 <span class=\"greek\">τεταγμέναι</span> <span class=\"greek\">περίοδοι</span> <span class=\"greek\">ἀστέρων</span>). <span class=\"greek\">κατὰ</span> <span class=\"greek\">καιροὺς</span> <span class=\"greek\">τεταγμένους</span> em tempos determinados 40:1 (cf. Polyb. 17, 1, 1).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> méd.=ativo (Hdt. et al.; 2 Km 20:5) <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρος</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐτάξατο</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰησοῦς</span> (isto é, <span class=\"greek\">πορεύεσθαι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:16</a>. <span class=\"greek\">ταξάμενοι</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">ἦλθον</span> fixaram-lhe um dia e vieram <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:23</a> (<span class=\"greek\">τασς</span>. <span class=\"greek\">ἡμέραν</span> como Polyb. 18, 19, 1; Jos., Ant. 9, 136).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0353-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταῦ, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταῦ</span> , <span class=\"greek\">τό</span> (Hippocr.; Pla., Cratyl. 364c) tau, numeral para 300 B 9:8; v. <span class=\"greek\">τ</span>´ (sinal numérico).</p></section></article>"};
